contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address newOwner, address attackTarget) public payable {
        require(newOwner != address(this));
        require(attackTarget != address(0));
        // deployer (this contract) is the initial owner
        bool first = c.setOwner(newOwner); if (__ESBMC_reverted()) return;
        require(first);
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;
        require(beforeOwner == newOwner);
        // now this contract is no longer the owner; attempt must revert
        bool reverted;
        c.setOwner(attackTarget); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && c.owner() == beforeOwner);
    }
    receive() external payable {}
}

